  if (helpScene === 'rescue')
    return '这张图偏向危险救援，不一定适合日常帮忙，请核对后选择。';
  if (helpScene === 'medical')
    return '这张图偏向医疗协助，请核对是否符合这次求助。';
  if (
    semantics.queryConceptId === 'aac:tonight' &&
    semantics.candidateMatch === 'approximate'
  )
    return '这张图只表示夜晚，没有表示“今天”；原文仍保留“今晚”，请确认是否适合。';
  if (
    semantics.queryConceptId === 'aac:eat-meal' &&
    semantics.candidateMatch === 'strong'
  )
    return '图中是围桌用餐，没有早午晚时间标记，请确认是否适合表达“吃饭”。';
  if (semantics.candidateMatch === 'strong')
    return '图中动作和目的地与当前表达相符，请确认是否适合。';
  if (semantics.candidateMatch === 'approximate')
    return '近似表达，可能缺少部分含义，请确认后采用。';
