// Retrieval eligibility is deliberately separate from automatic adoption.
// Source meaning must support the query; a provider's result rank is not proof.
function isPictogramSearchCandidateRelevant(value) {
  const semantics = normalizePictogramSemantics(value);
  if (!semantics || semantics.relation === 'conflict') return false;
  if (
    semantics.mappingVersion === PICTOGRAM_SEMANTICS_VERSION &&
    SEMANTIC_CANDIDATES.some(
      row =>
        row.concept === semantics.queryConceptId &&
        semantics.candidateEvidence === candidateEvidence(row) &&
        semantics.candidateMatch === row.match
    )
  )
    return true;
  // Broad related queries may only admit the individually audited source IDs.
  if (
    getSemanticCandidateQueries(semantics.queryText).some(
      query => key(query) === key(semantics.lookupText)
    )
  )
    return false;
  if (
    semantics.mappingVersion === PICTOGRAM_SEMANTICS_VERSION &&
    semantics.relation === 'reviewed'
  )
    return true;
  if (
    semantics.queryConceptId &&
    semantics.conceptId === semantics.queryConceptId
  )
    return true;
  const phrase = text =>
    key(text)
      .replace(/^to\s+/, '')
      .replace(/[-_\s]+/g, ' ');
  const queries = [semantics.queryText, semantics.lookupText]
    .map(phrase)
    .filter(Boolean);
  return semantics.sourceLabels.some(label => queries.includes(phrase(label)));
}

// Rank retrieval evidence, not adoption permission. Rebuild from the actual
// source identity so copied candidateMatch/concept fields cannot boost a hit.
// No usage/popularity/cache bonus may outrank meaning. Legacy manual candidates
// remain reviewable, but never receive semantic evidence they did not have.
function assessPictogramCandidate(token, pictogram) {
  const reject = reason => ({ eligible: false, tier: null, reason });
  if (
    !pictogram ||
    !clean(pictogram.id) ||
    !clean(pictogram.image || pictogram.imageUrl)
  )
    return reject('missing-image');
  if (!pictogram.semantics)
    return { eligible: true, tier: 5, reason: 'legacy-needs-review' };
  const value = normalizePictogramSemantics(pictogram.semantics);
  if (!value || value.mappingVersion !== PICTOGRAM_SEMANTICS_VERSION)
    return reject('stale-evidence');
  const concept = getPictogramConcept(token);
  const queryConcept = getPictogramConcept(value.queryText);
  if (
    key(token) !== key(value.queryText) &&
    !(concept && queryConcept && queryConcept.id === concept.id)
  )
    return reject('different-expression');
  const source = pictogram.source || {};
  if (!clean(source.provider) || !clean(String(source.originalId || '')))
    return reject('missing-source');
  const rebuilt = buildPictogramSemantics({
    token,
    query: value.lookupText,
    locale: value.sourceLanguage,
    provider: source.provider,
    originalId: source.originalId,
    sourceLabels: value.sourceLabels,
    sourceDefinitions: value.sourceDefinitions,
    sourceCategories: value.sourceCategories
  });
  // Mixed qualified senses (e.g. go home + leave home) are ambiguous even when
  // the requested phrase also appears among the labels. Ask for another image.
  if (value.relation === 'conflict' || rebuilt.relation === 'conflict')
    return reject('conflicting-meaning');
  if (!isPictogramSearchCandidateRelevant(rebuilt))
    return reject('unsupported-meaning');
  // Refresh display evidence, but never relax a stored review requirement.
  rebuilt.requiresReview = value.requiresReview || rebuilt.requiresReview;
  const accept = (tier, reason) => ({
    eligible: true,
    tier,
    reason,
    semantics: rebuilt
  });
  if (rebuilt.relation === 'reviewed') return accept(0, 'reviewed-source');
  const helpScene = getHelpCandidateScene(rebuilt);
  if (helpScene === 'rescue') return accept(4, 'specialized-rescue-scene');
  if (helpScene === 'medical') return accept(3, 'specialized-medical-scene');
  if (rebuilt.candidateMatch === 'strong')
    return accept(1, 'audited-action-destination');
  if (rebuilt.conceptId && rebuilt.conceptId === rebuilt.queryConceptId)
    return accept(2, 'qualified-source-concept');
  if (rebuilt.candidateMatch === 'approximate')
    return accept(4, 'audited-partial-meaning');
  return accept(3, 'source-label-match');
}

function rankPictogramCandidates(token, candidates, { limit = 4 } = {}) {
  const seenIds = new Set();
  const seenSources = new Set();
  const count = Number.isInteger(limit) && limit >= 0 ? limit : 4;
  return (Array.isArray(candidates) ? candidates : [])
    .map((pictogram, index) => ({
      pictogram,
      index,
      assessment: assessPictogramCandidate(token, pictogram)
    }))
    .filter(item => item.assessment.eligible)
    .sort((a, b) => a.assessment.tier - b.assessment.tier || a.index - b.index)
    .filter(({ pictogram }) => {
      const source = pictogram.source || {};
      const identity =
        source.provider && source.originalId
          ? JSON.stringify([
              source.provider,
              String(source.originalId),
              source.repoKey || ''
            ])
          : null;
      if (seenIds.has(pictogram.id) || (identity && seenSources.has(identity)))
        return false;
      seenIds.add(pictogram.id);
      if (identity) seenSources.add(identity);
      return true;
    })
    .slice(0, count)
    .map(item =>
      item.assessment.semantics
        ? { ...item.pictogram, semantics: item.assessment.semantics }
        : item.pictogram
    );
}

